"""Generate the main-site owner console using the shared account/MFA controls."""
from pathlib import Path
import re
ROOT=Path(__file__).resolve().parents[1]
def build():
 home=(ROOT/'index.html').read_text();legacy=(ROOT/'forgeeks-admin.html').read_text()
 nav=re.search(r'<div class="d-bar">.*?</div>\s*</div>\s*</div>',home,re.S).group().replace(' aria-current="page"','')
 mfa=re.search(r'<section class="panel"><h2>Verify administrator access.*?</section>',legacy,re.S).group()
 credit=re.search(r'<form class="panel" id="admin-credit-form">.*?</form>',legacy,re.S).group()
 price=re.search(r'<form class="panel" id="admin-price-form">.*?</form>',legacy,re.S).group()
 panels='''
<section class="panel" id="setup"><h2>Checkout setup</h2><p>Support: <a href="mailto:hello@lightningeg.com">hello@lightningeg.com</a>. The QR is private and appears only in a signed-in customer’s accepted checkout.</p>
<form id="store-settings"><div class="fields two"><label>Receiving InstaPay address<input name="address" maxlength="200" required></label><label>Exact recipient name shown by InstaPay<input name="recipient" maxlength="200" required></label></div><label>Private QR image<input type="file" name="qr" accept="image/png,image/jpeg,image/webp"></label><p id="store-qr-status">Upload only when changing the QR.</p><label>Processing instructions<textarea name="processing" minlength="20" maxlength="400" required></textarea></label><label class="chk"><input name="enabled" type="checkbox"><span>Open checkout after checking the receiving details and QR</span></label><button class="btn" type="submit">Save checkout settings</button></form><p id="store-settings-status" role="status"></p></section>
<section class="panel" id="pricing"><h2>Amount-based coin pricing</h2><p>Customers enter an EGP amount. The quote freezes the rate and bonus before payment; later pricing changes affect new requests.</p><form id="store-pricing"><div class="fields three"><label>Coins per 1 EGP<input name="rate" type="number" min="1" max="1000" required></label><label>Minimum EGP<input name="minimum" type="number" min="1" required></label><label>Maximum EGP<input name="maximum" type="number" min="1" max="100000" required></label></div><label>Bonus thresholds (EGP:percent, one per line)<textarea name="tiers" rows="3" placeholder="100:5&#10;500:10&#10;1000:15"></textarea></label><label class="chk"><input name="enabled" type="checkbox"><span>Allow new amount quotes</span></label><button class="btn" type="submit">Save pricing</button></form><p id="store-pricing-status" role="status"></p></section>
<section class="panel" id="bank"><h2>Record money received</h2><p>Open your own InstaPay or bank account first. A customer receipt alone is not proof that the money arrived. Each receiving reference is recorded once.</p><form id="store-bank-record"><div class="fields two"><label>Receiving bank reference<input name="reference" minlength="6" maxlength="100" required></label><label>Actual EGP received<input name="amount" type="number" step="0.01" min="0.01" required></label><label>Received at (your local time)<input name="received" type="datetime-local" required></label><label>Checkout request ID (leave empty if unmatched)<input name="request" autocomplete="off"></label><label>Sender InstaPay address (if known)<input name="sender" maxlength="200"></label><label>Lightning email in the transfer note (if present)<input name="email" type="email" maxlength="254"></label></div><label>Reconciliation note<textarea name="note" minlength="5" maxlength="500" required></textarea></label><label class="chk"><input name="confirmed" type="checkbox" required><span>I independently confirmed these funds reached the receiving account.</span></label><button class="btn" type="submit">Record bank transfer</button></form><p id="store-bank-status" role="status"></p><h3>Bank journal</h3><div class="row"><select id="store-bank-filter" aria-label="Bank journal filter"><option value="unmatched">Unmatched</option><option value="all">All transfers</option></select><button class="btn ghost" type="button" id="store-bank-refresh">Refresh journal</button></div><div id="store-bank-list"></div><button class="btn ghost" id="store-bank-more" type="button">Load more</button></section>
<section class="panel" id="requests"><h2>Reconcile customer requests</h2><p>Match the member email, sender address, receipt and receiving references. Multiple partial transfers can fund one request. Coins are credited only when the verified bank total equals the accepted quote.</p><div class="row"><select id="store-request-filter" aria-label="Request status"><option value="pending">Pending</option><option value="approved">Approved</option><option value="rejected">Rejected</option><option value="cancelled">Cancelled</option></select><input id="store-request-search" type="email" placeholder="Filter by checkout email" aria-label="Checkout email"><button class="btn ghost" type="button" id="store-request-refresh">Refresh requests</button></div><p id="store-request-status" role="status"></p><div id="store-request-list"></div><button class="btn ghost" id="store-request-more" type="button">Load more</button></section>
<section class="panel" id="social"><h2>Review social posts</h2><p>Open the LinkedIn or Reddit post, check the member’s verification code and link back to Lightning, then choose coins and/or leaderboard points. A post can receive each reward once; a member can earn coins for at most three posts in 30 days.</p><div class="row"><select id="store-social-filter" aria-label="Post status"><option value="pending">Pending</option><option value="published">Published</option><option value="rejected">Rejected</option></select><button class="btn ghost" type="button" id="store-social-refresh">Refresh posts</button></div><div id="store-social-list"></div><button class="btn ghost" id="store-social-more" type="button">Load more</button></section>
<section class="panel"><h2>Receipt retention</h2><p>Delete eligible image files older than 90 days. Pending payment evidence is protected; financial ledger records remain.</p><button class="btn ghost" id="store-retention" type="button">Remove expired receipt files</button><p id="store-retention-status" role="status"></p></section>
'''
 page=f'''<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><meta name="robots" content="noindex,nofollow"><title>Owner operations · Lightning</title><link rel="stylesheet" href="https://fonts.googleapis.com/css2?family=Bricolage+Grotesque:wght@700;800&amp;family=Manrope:wght@500;600;700;800&amp;display=swap"><link rel="stylesheet" href="css/landing.css"><link rel="stylesheet" href="css/theme.css"><link rel="stylesheet" href="css/forgeeks-account.css"><link rel="stylesheet" href="css/site-account.css?v=20261025-reaudit-1"><link rel="stylesheet" href="css/store-admin.css?v=20261025-reaudit-1"><link rel="stylesheet" href="css/footer.css"><script src="js/theme.js"></script></head><body data-account-page="account.html" data-main-store="true" data-owner-console="amount">{nav}<main class="wrap acct ops"><section class="acct-top"><h1>Owner operations.</h1><p class="lede">Configure checkout, reconcile incoming transfers and review the coins you issue.</p><p id="store-access" role="status">Checking account access…</p><a class="btn" id="store-signin" href="account.html?next=admin.html" hidden>Sign in</a><div id="store-owner" hidden>{mfa}<button class="btn ghost" id="store-unlock" type="button">Refresh verified session</button><p id="store-overview-status" role="status"></p><div id="store-overview" class="ops-overview"></div><nav class="ops-nav" aria-label="Owner tools"><a href="#setup">Checkout</a><a href="#pricing">Pricing</a><a href="#bank">Bank journal</a><a href="#requests">Requests</a><a href="#social">Social posts</a><a href="#credits">Manual credits</a></nav><fieldset id="store-tools" disabled>{panels}<section id="credits">{credit}{price}</section><p><a href="forgeeks-admin.html?advanced=1">Advanced contributor and moderation tools</a></p></fieldset></div></section></main><footer></footer><script src="js/vendor/supabase-2.118.0.js"></script><script src="js/forgeeks-config.js"></script><script src="js/forgeeks-auth.js?v=20261025-reaudit-1"></script><script src="js/admin-operations.js?v=20261025-mfa-1"></script><script src="js/story-moderation.js?v=20261025-reaudit-1"></script><script src="js/store-admin.js?v=20261025-mfa-1"></script><script src="js/nav-menu.js"></script></body></html>'''
 (ROOT/'admin.html').write_text(page)
if __name__=='__main__':build()
